# ======================= INTRODUCCIÓN A LA ECONOMÍA =======================
U={1:"Unidad 1 · Objeto y método",2:"Unidad 2 · Aspectos microeconómicos",3:"Unidad 3 · El Estado en una economía mixta",4:"Unidad 4 · Aspectos macroeconómicos"}
guide(dict(slug="introduccion-economia",dir="ie",h1="Introducción a la Economía",nombre="Introducción a la Economía",cod="1503700",
  desc="Programa 1503700: escasez y costo de oportunidad, economía positiva y normativa, flujo circular y frontera de posibilidades, oferta, demanda y elasticidades, fallas de mercado y papel del Estado, y las grandes variables macroeconómicas con el caso colombiano.",
  colors=["#a0441b","#f6e2d8","#e59a78","#4a1d0a"],trunk="Tronco: las cuatro unidades del programa",
  intro='Resumen y guía de estudio del programa 1503700, con Mankiw, Case y Fair, Samuelson y Nordhaus, y el libro de Cárdenas sobre la economía colombiana. Para practicar con gráficas interactivas de oferta, demanda y excedentes, usa <a href="principios-micro.html">Principios de Microeconomía</a>; para el PIB, la inflación y el desempleo, <a href="principios-macro.html">Principios de Macroeconomía</a>.',
  res="Escasez, costo de oportunidad, flujo circular, oferta y demanda, elasticidad, Estado y macroeconomía básica de Colombia."),U,[
 ("objeto",1,"Escasez, elección y método de la economía","tarjetas",[
  ("El problema económico",p("La economía estudia cómo las sociedades administran <b>recursos escasos</b> para satisfacer necesidades ilimitadas. Toda elección tiene un <b>costo de oportunidad</b>: el valor de la mejor alternativa a la que se renuncia.","Toda sociedad responde tres preguntas: <b>qué</b> producir, <b>cómo</b> producirlo y <b>para quién</b>. Las economías de mercado las responden con precios; las planificadas, con decisiones centrales; las economías reales son <b>mixtas</b>.")),
  ("Diez principios (Mankiw)",ul("Las personas enfrentan disyuntivas.","El costo de algo es aquello a lo que se renuncia.","Las personas racionales piensan en términos marginales.","Las personas responden a incentivos.","El comercio puede mejorar el bienestar de todos.","Los mercados suelen ser una buena forma de organizar la actividad económica.","El gobierno a veces puede mejorar los resultados del mercado.","El nivel de vida depende de la capacidad de producir bienes y servicios (productividad).","Los precios suben cuando el gobierno imprime demasiado dinero.","A corto plazo hay una disyuntiva entre inflación y desempleo.")),
  ("Positiva y normativa; micro y macro",p("La economía <b>positiva</b> describe y explica cómo es la economía («si sube el salario mínimo, cae el empleo de baja calificación»); la <b>normativa</b> dice cómo debería ser («el salario mínimo debería subir»). La <b>microeconomía</b> estudia decisiones de hogares y empresas y mercados particulares; la <b>macroeconomía</b>, los agregados: producción, inflación, desempleo, crecimiento.")),
  ("Modelos",p("Un modelo simplifica la realidad con supuestos para aislar lo esencial («ceteris paribus»: lo demás constante). El <b>flujo circular</b> muestra cómo hogares y empresas se relacionan en los mercados de bienes y de factores. La <b>frontera de posibilidades de producción</b> (FPP) muestra las combinaciones máximas de dos bienes con los recursos y la tecnología dados: los puntos sobre ella son eficientes, los internos ineficientes, los externos inalcanzables; su pendiente es el costo de oportunidad, creciente si la frontera es cóncava; el crecimiento la desplaza hacia afuera."))]),
 ("colombia",1,"Pensamiento económico y problemas de Colombia","tiempo",[
  ("Breve historia de las ideas",p("Mercantilistas (riqueza = metales preciosos, superávit comercial), fisiócratas (la tierra como única fuente de excedente, Quesnay), clásicos (Smith, Ricardo, Malthus, Mill: división del trabajo, valor trabajo, libre comercio), Marx (explotación y crisis del capitalismo), marginalistas y neoclásicos (Jevons, Menger, Walras, Marshall: utilidad marginal, equilibrio), Keynes (demanda agregada y desempleo involuntario), y desde la posguerra la síntesis, el monetarismo, las expectativas racionales y las nuevas teorías. La ruta de <a href=\"historia-pensamiento.html\">Historia del Pensamiento Económico</a> profundiza.")),
  ("Problemas económicos de Colombia",ul("Informalidad laboral alta y desempleo estructural de dos dígitos durante buena parte de su historia reciente.","Una de las distribuciones del ingreso más desiguales de América Latina.","Dependencia de exportaciones de bienes primarios (petróleo, carbón, café) y vulnerabilidad a sus precios.","Baja productividad y brechas regionales grandes.","Conflicto armado, economías ilegales e instituciones débiles en parte del territorio.","Estabilidad macroeconómica relativamente alta: banco central independiente desde la Constitución de 1991, regla fiscal desde 2011."),p("Cárdenas (Introducción a la economía colombiana) es la referencia del programa para estos temas."))]),
 ("mercado",2,"Oferta, demanda y equilibrio","tarjetas",[
  ("Demanda",p("La cantidad demandada cae cuando sube el precio (<b>ley de la demanda</b>), por el efecto sustitución y el efecto ingreso. La curva se <b>desplaza</b> por cambios en el ingreso (bienes normales e inferiores), en los precios de bienes relacionados (sustitutos y complementarios), en los gustos, en las expectativas y en el número de compradores. La demanda de mercado es la suma horizontal de las individuales.")),
  ("Oferta",p("La cantidad ofrecida sube con el precio. La curva se desplaza por cambios en los precios de los insumos, la tecnología, las expectativas, el número de vendedores y los impuestos o subsidios. Distinguir <b>movimiento a lo largo</b> de la curva (cambia el precio del propio bien) de <b>desplazamiento</b> de la curva (cambia otro determinante) es clave en los exámenes.")),
  ("Equilibrio",p("En el equilibrio la cantidad demandada iguala la ofrecida. Con un precio por encima hay <b>excedente</b> (exceso de oferta) y el precio tiende a bajar; por debajo hay <b>escasez</b> y tiende a subir. Análisis en tres pasos: ¿qué curva se desplaza?, ¿hacia dónde?, ¿qué pasa con el precio y la cantidad? Si ambas curvas se mueven, uno de los dos efectos queda ambiguo.")),
  ("Elasticidades",ul("Precio de la demanda: %ΔQ/%ΔP. Elástica si es mayor que 1 en valor absoluto; con demanda inelástica, subir el precio aumenta el ingreso total.","Ingreso: positiva para bienes normales (mayor que 1, de lujo), negativa para inferiores.","Cruzada: positiva para sustitutos, negativa para complementarios.","Precio de la oferta: mayor a largo plazo que a corto plazo."),p("Método del punto medio: %Δ = ΔQ/[(Q₁ + Q₂)/2]."))]),
 ("estado",3,"El Estado en una economía mixta","tarjetas",[
  ("Por qué interviene",ul("<b>Fallas de mercado</b>: externalidades (contaminación), bienes públicos (defensa, alumbrado), poder de mercado (monopolios), información asimétrica.","<b>Equidad</b>: redistribución del ingreso.","<b>Estabilización</b>: reducir los ciclos con política fiscal y monetaria."),p("Musgrave resume las funciones del Estado en asignación, distribución y estabilización.")),
  ("Instrumentos",ul("Impuestos y subsidios. Un impuesto crea una cuña entre el precio que paga el comprador y el que recibe el vendedor; lo soporta más el lado menos elástico.","Controles de precios: un precio máximo por debajo del equilibrio crea escasez; un precio mínimo por encima (como el salario mínimo) crea excedente.","Regulación, provisión pública y empresas estatales."),p("También existen <b>fallas del Estado</b>: búsqueda de rentas, captura regulatoria, problemas de información e incentivos."))]),
 ("macro",4,"Aspectos macroeconómicos básicos","tarjetas",[
  ("Las grandes variables",ul("<b>PIB</b>: valor de mercado de los bienes y servicios finales producidos en un país en un periodo. PIB = C + I + G + (X − M). Nominal frente a real (a precios constantes).","<b>Inflación</b>: aumento sostenido del nivel general de precios; en Colombia se mide con el IPC del DANE.","<b>Desempleo</b>: desocupados que buscan trabajo sobre la población económicamente activa (fuerza laboral).","<b>Tasa de interés, tasa de cambio y balanza de pagos</b>.")),
  ("Política económica",p("La <b>política fiscal</b> (gasto e impuestos) la hace el gobierno; la <b>monetaria</b>, el Banco de la República, que en Colombia usa la tasa de interés de política para cumplir una meta de inflación (3 %). El largo plazo depende del crecimiento de la productividad; el corto plazo, de la demanda agregada."))])],
 [(1,"Escasez","Situación en que los recursos no alcanzan para satisfacer todas las necesidades."),(1,"Costo de oportunidad","Valor de la mejor alternativa sacrificada al elegir."),(1,"Pensamiento marginal","Comparar el beneficio y el costo de una unidad adicional."),(1,"Economía positiva","Describe lo que es; se puede contrastar con datos."),(1,"Economía normativa","Afirma lo que debería ser; implica juicios de valor."),(1,"Ceteris paribus","Supuesto de que los demás factores permanecen constantes."),(1,"Flujo circular","Modelo de las relaciones entre hogares y empresas en los mercados de bienes y de factores."),(1,"Frontera de posibilidades de producción","Combinaciones máximas de dos bienes con recursos y tecnología dados."),(2,"Ley de la demanda","La cantidad demandada cae al subir el precio, todo lo demás constante."),(2,"Bien inferior","Su demanda cae cuando sube el ingreso."),(2,"Bienes sustitutos","Si sube el precio de uno, aumenta la demanda del otro."),(2,"Bienes complementarios","Si sube el precio de uno, cae la demanda del otro."),(2,"Equilibrio","Precio al que la cantidad demandada iguala la ofrecida."),(2,"Elasticidad precio","Cambio porcentual de la cantidad ante un cambio de 1 % en el precio."),(3,"Externalidad","Efecto de una actividad sobre terceros que no se refleja en el precio."),(3,"Bien público","No rival y no excluible."),(3,"Precio máximo","Límite legal superior al precio; si está por debajo del equilibrio, causa escasez."),(4,"PIB","Valor de la producción final de un país en un periodo."),(4,"IPC","Índice de precios al consumidor; base para medir la inflación."),(4,"Tasa de desempleo","Desocupados / población económicamente activa.")],
 [(1,"El costo de oportunidad de estudiar en la universidad incluye:",["Solo la matrícula","La matrícula y el ingreso que se deja de ganar","Solo los libros","Nada, porque es una inversión"],1,"El ingreso sacrificado es el mayor componente."),(1,"«El salario mínimo debería subir 10 %» es una afirmación:",["Positiva","Normativa","Macroeconómica positiva","Falsa"],1,"Implica un juicio de valor."),(1,"Un punto dentro de la FPP indica:",["Producción inalcanzable","Uso ineficiente de recursos","Crecimiento","Máxima eficiencia"],1,"Se podría producir más de ambos bienes."),(1,"Una FPP cóncava refleja:",["Costo de oportunidad constante","Costo de oportunidad creciente","Desempleo","Comercio"],1,"Los recursos no son igualmente aptos."),(2,"Si sube el ingreso y la demanda de un bien cae, el bien es:",["Normal","Inferior","De lujo","Complementario"],1,"Elasticidad ingreso negativa."),(2,"Si sube el precio del café, la demanda de azúcar (complemento):",["Sube","Baja","No cambia","Se vuelve elástica"],1,"Se consume menos café."),(2,"Una helada destruye cosechas de papa. En el mercado de la papa:",["Sube la oferta","Cae la oferta, sube el precio y cae la cantidad","Sube la demanda","Baja el precio"],1,"Desplazamiento de la oferta a la izquierda."),(2,"Con demanda inelástica, si sube el precio, el ingreso total:",["Baja","Sube","No cambia","Se hace cero"],1,"La cantidad cae proporcionalmente menos."),(3,"Un precio máximo por debajo del equilibrio genera:",["Excedente","Escasez","Equilibrio","Inflación"],1,"La cantidad demandada supera la ofrecida."),(3,"El alumbrado público es un ejemplo de:",["Bien privado","Bien público","Bien inferior","Monopolio natural"],1,"No rival y no excluible."),(4,"El PIB no incluye:",["Bienes de consumo","La compra de una casa usada","Gasto del gobierno","Exportaciones"],1,"No es producción del periodo."),(4,"En Colombia la política monetaria la conduce:",["El Ministerio de Hacienda","El Banco de la República","El DANE","El Congreso"],1,"Banco central independiente desde 1991.")],
 [(1,"Explique con un ejemplo de su vida el concepto de costo de oportunidad y cómo se representa en una FPP.",["Definición.","Ejemplo con valores.","FPP: pendiente como costo de oportunidad.","Por qué es creciente."]),(2,"Analice qué pasa con el precio y la cantidad de arroz si sube el precio de los fertilizantes y al mismo tiempo crece la población.",["Desplazamiento de la oferta a la izquierda.","Desplazamiento de la demanda a la derecha.","Precio sube; cantidad ambigua.","Gráfica."]),(3,"¿Por qué un Estado interviene en una economía de mercado? Dé ejemplos colombianos.",["Fallas de mercado.","Equidad y redistribución.","Estabilización.","Fallas del Estado."]),(4,"Describa la situación macroeconómica reciente de Colombia usando PIB, inflación y desempleo.",["Definiciones.","Datos recientes del DANE y del Banco de la República.","Relación entre variables.","Política económica."])],
 [(1,"1776","Smith, La riqueza de las naciones","Nace la economía política clásica."),(1,"1817","Ricardo, Principios de economía política","Valor, distribución y ventaja comparativa."),(1,"1867","Marx, El capital (tomo I)","Crítica de la economía política."),(1,"1871–1874","Revolución marginalista","Jevons, Menger y Walras."),(1,"1890","Marshall, Principios de economía","Oferta, demanda y equilibrio parcial."),(1,"1936","Keynes, Teoría general","Nace la macroeconomía moderna."),(1,"1948","Samuelson, Economía","El manual que difundió la síntesis neoclásica."),(4,"1923","Creación del Banco de la República","Tras la Misión Kemmerer."),(4,"1991","Nueva Constitución de Colombia","Banco de la República independiente con mandato de estabilidad de precios.")])

# ======================= ECONOMÍA CLÁSICA =======================
U={1:"Unidad 1 · Introducción",2:"Unidad 2 · El sistema de producción",3:"Unidad 3 · Precios de producción",4:"Unidad 4 · Precios naturales en la historia",5:"Unidad 5 · Precios de mercado"}
guide(dict(slug="economia-clasica",dir="ec",h1="Economía Clásica",nombre="Economía Clásica",cod="1503720",
  desc="Programa 1503720: objeto y método de la economía, el sistema de producción clásico (coeficientes técnicos y excedente), precios de producción en Ricardo y en Sraffa, teoría del salario, y la historia del pensamiento clásico sobre precios naturales y de mercado.",
  colors=["#7a5a12","#f3ebd6","#d6b469","#382805"],trunk="Tronco: las cinco unidades del programa",
  intro='Resumen y guía de estudio del programa 1503720, siguiendo las notas de Eduardo Bolaños (Teoría clásica de los precios) y a Cartelier (Excedente y reproducción). Los laboratorios de Sraffa, Ricardo y Smith están en <a href="historia-pensamiento.html">Historia del Pensamiento Económico</a>.',
  res="Excedente y reproducción, coeficientes técnicos, precios de producción de Ricardo y Sraffa, salario, precios naturales y de mercado."),U,[
 ("objeto",1,"Las ciencias económicas, su objeto y su método","tarjetas",[
  ("Dos grandes teorías del mercado",p("La teoría económica tiene dos programas para explicar cómo se coordinan los individuos en una economía descentralizada: la teoría <b>clásica del excedente</b> (Petty, Quesnay, Smith, Ricardo, Marx, Sraffa), que parte de las condiciones técnicas de producción y de la distribución entre clases sociales, y la teoría del <b>equilibrio general</b> neoclásico (Walras), que parte de las preferencias, las dotaciones y la tecnología de individuos. Benetti y Cataño discuten el alcance de cada una.")),
  ("El método",p("La economía clásica razona sobre <b>posiciones de largo plazo</b>, con una tasa de ganancia uniforme gracias a la competencia (libre movilidad del capital entre sectores). Abstrae las fluctuaciones de corto plazo para hallar los <b>precios naturales</b> alrededor de los cuales gravitan los precios de mercado."))]),
 ("sistema",2,"El sistema de producción clásico","tarjetas",[
  ("Producción de mercancías por medio de mercancías",p("Un sistema de producción se describe con los <b>coeficientes técnicos</b> \\(a_{ij}\\): cantidad del bien \\(i\\) necesaria para producir una unidad del bien \\(j\\), y \\(l_j\\): trabajo por unidad de \\(j\\). El sistema es <b>productivo</b> si produce más de lo que consume como medios de producción.")),
  ("El excedente",p("El <b>excedente</b> es el producto neto que queda después de reponer los medios de producción y la subsistencia de los trabajadores. Su existencia y su reparto (ganancias, rentas, salarios por encima de la subsistencia) definen la sociedad: en la fisiocracia, la tierra produce el excedente (Tableau économique de Quesnay); en Smith y Ricardo, todo el trabajo productivo; en Marx, la plusvalía extraída al trabajo."),p("Formas de distribución del excedente: a los capitalistas como ganancia proporcional al capital adelantado (tasa uniforme), a los terratenientes como renta, y eventualmente a los trabajadores."))]),
 ("precios",3,"Precios de producción: Ricardo y Sraffa","tarjetas",[
  ("Sin dinero",p("La teoría clásica de los precios de producción determina <b>precios relativos</b> sin necesidad de dinero: el dinero es un velo. Bolaños discute la necesidad de reintegrar el dinero para explicar el mercado.")),
  ("Ricardo",p("En la versión ricardiana, el valor de cambio depende de la cantidad de trabajo incorporado, modificado por la distribución cuando las mercancías tienen distinta relación capital/trabajo o distintos tiempos de producción. La búsqueda de una <b>medida invariable del valor</b> lleva a Ricardo a un bien producido con proporciones medias.")),
  ("Teoría clásica del salario",p("El salario natural es el que permite a los trabajadores subsistir y reproducirse según las costumbres de la época (componente histórico y moral). El fondo de salarios y la población ajustan el salario de mercado hacia el natural.")),
  ("Sraffa (1960)",p("Con salario pagado post factum, el sistema de precios es \\(p=(1+r)pA+wl\\): para una tasa de ganancia \\(r\\) dada (o un salario dado), se obtienen los precios relativos y el otro distributivo. Hay un grado de libertad: la distribución no está determinada por la técnica. La relación entre salario y ganancia es inversa (frontera salario-ganancia). La <b>mercancía patrón</b> hace esa relación lineal: \\(w=1-r/R\\)."),p("Tipos de precio relativo: con \\(r=0\\) los precios son proporcionales al trabajo incorporado; con \\(w=0\\), a los requerimientos del sistema."))]),
 ("naturales",4,"El pensamiento clásico sobre los precios naturales","tiempo",[
  ("De Petty a Ricardo",ul("<b>Petty</b>: el precio natural de los bienes depende del trabajo y la tierra; busca un «par» entre ambos.","<b>Cantillon</b>: valor intrínseco como cantidad de tierra y trabajo.","<b>Quesnay</b>: la reproducción del sistema y el excedente agrícola.","<b>Smith</b>: el precio natural es el que paga salario, ganancia y renta a sus tasas naturales (teoría de la suma de componentes); en el «estado primitivo» rige el trabajo.","<b>Ricardo</b>: teoría del valor trabajo y crítica de la suma de componentes; renta diferencial."),p("<b>Marx</b> transforma valores en precios de producción y <b>Sraffa</b> resuelve rigurosamente el sistema; estos temas continúan en Economía Política."))]),
 ("mercado",5,"Precios de mercado y gravitación","tarjetas",[
  ("Gravitación",p("Para Smith los precios de mercado se forman por la relación entre la cantidad llevada al mercado y la <b>demanda efectiva</b> (la de quienes están dispuestos a pagar el precio natural). Si el precio de mercado supera el natural, la tasa de ganancia de ese sector sube, entra capital y la oferta aumenta hasta que el precio regresa: es el mecanismo de <b>gravitación</b>.")),
  ("Debates",p("Los modelos de gravitación (cross-dual dynamics) estudian si este proceso converge. Cartelier y Benetti señalan que la teoría clásica explica las posiciones naturales mejor que el proceso de mercado que conduciría a ellas; en ello radica la importancia de introducir explícitamente el dinero."))])],
 [(1,"Teoría del excedente","Enfoque clásico que explica precios y distribución a partir del producto neto."),(1,"Precio natural","Precio de largo plazo que remunera los factores a sus tasas naturales."),(1,"Tasa uniforme de ganancia","Igualación de rentabilidades entre sectores por la competencia."),(2,"Coeficiente técnico","Cantidad de un insumo por unidad de producto."),(2,"Sistema productivo","El que produce más de cada bien de lo que usa como insumo."),(2,"Excedente","Producto neto tras reponer insumos y subsistencia."),(2,"Tableau économique","Esquema de Quesnay de la circulación del producto entre clases."),(3,"Valor trabajo incorporado","Trabajo directo e indirecto necesario para producir un bien."),(3,"Medida invariable del valor","Patrón cuyo valor no cambia con la distribución, buscado por Ricardo."),(3,"Salario natural","Salario que permite la subsistencia y reproducción de los trabajadores."),(3,"Frontera salario-ganancia","Relación inversa entre salario y tasa de ganancia."),(3,"Mercancía patrón","Mercancía compuesta de Sraffa que hace lineal la relación salario-ganancia."),(4,"Suma de componentes","Teoría de Smith: precio natural = salarios + ganancias + rentas."),(4,"Renta diferencial","Renta que surge de la distinta fertilidad de las tierras (Ricardo)."),(5,"Demanda efectiva (Smith)","Demanda de quienes pagan el precio natural."),(5,"Gravitación","Convergencia de los precios de mercado hacia los naturales.")],
 [(1,"La teoría clásica se distingue de la neoclásica en que parte de:",["Las preferencias individuales","Las condiciones técnicas y la distribución entre clases","La utilidad marginal","El equilibrio de corto plazo"],1,"Programa del excedente."),(2,"Para los fisiócratas, el excedente se genera en:",["La industria","La agricultura","El comercio","El Estado"],1,"Producto neto agrícola."),(2,"Un sistema es productivo si:",["Usa más insumos de los que produce","Produce un excedente de cada bien","No usa trabajo","Tiene dinero"],1,"Producto neto no negativo."),(3,"En el sistema de Sraffa, la distribución:",["Está determinada por la técnica","Tiene un grado de libertad","No afecta los precios","Depende de la demanda"],1,"Se fija r o w desde fuera."),(3,"Con tasa de ganancia cero, los precios son proporcionales a:",["Los salarios","El trabajo incorporado","La demanda","El dinero"],1,"Caso de los valores trabajo."),(3,"La relación entre salario y ganancia en Sraffa es:",["Directa","Inversa","Nula","Aleatoria"],1,"Frontera salario-ganancia."),(3,"La mercancía patrón sirve para:",["Medir la utilidad","Hacer lineal la relación w-r","Fijar el tipo de cambio","Calcular la renta"],1,"w = 1 − r/R."),(4,"La teoría de Smith del precio natural como suma de salario, ganancia y renta fue criticada por:",["Quesnay","Ricardo","Petty","Walras"],1,"Ricardo defendía el valor trabajo."),(5,"Si el precio de mercado supera el natural:",["Sale capital del sector","Entra capital y aumenta la oferta","Baja el salario natural","Nada ocurre"],1,"Mecanismo de gravitación."),(5,"La demanda efectiva en Smith es:",["Toda la demanda","La de quienes pagan el precio natural","La del gobierno","La demanda agregada keynesiana"],1,"Concepto distinto del keynesiano.")],
 [(2,"Explique el concepto de excedente y cómo cambia su origen entre fisiócratas, Smith y Ricardo.",["Definición de excedente.","Producto neto agrícola en Quesnay.","Trabajo productivo en Smith.","Ricardo y la renta diferencial."]),(3,"Presente el sistema de precios de Sraffa con dos bienes y explique el grado de libertad de la distribución.",["Ecuaciones de precios.","Numerario.","Relación w-r.","Casos extremos r = 0 y w = 0."]),(5,"¿Cómo explican los clásicos la relación entre precios de mercado y precios naturales?",["Demanda efectiva.","Movilidad del capital y tasa de ganancia.","Gravitación.","Críticas y el papel del dinero."])],
 [(4,"1662","Petty, Tratado de impuestos","Trabajo y tierra como fuentes del valor."),(4,"1755","Cantillon, Ensayo sobre la naturaleza del comercio","Valor intrínseco."),(2,"1758","Quesnay, Tableau économique","Circulación del producto neto."),(4,"1776","Smith, La riqueza de las naciones","Precio natural y de mercado."),(4,"1817","Ricardo, Principios","Valor trabajo y renta diferencial."),(4,"1867","Marx, El capital","Plusvalía y precios de producción."),(3,"1960","Sraffa, Producción de mercancías por medio de mercancías","Reconstrucción de la teoría clásica de los precios.")])

